window.MG_LAZY_DATA["data/lazy/resources/security-v26-076-05f16d30d0a7cae8.json"]={sha256:"05f16d30d0a7cae80539641ac3f8e47aa6b4164f1ee48dc6b5603e96f2ddf646",value:{"sources":[{"id":"v26-case-e792035f6caa8caa","url":"https://kubernetes.io/docs/tasks/debug/debug-cluster/audit/","title":"Kubernetes auditing","titleEn":"Kubernetes auditing","publisher":"Kubernetes","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-076","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-076","related":[{"id":"security-v26-077","referenceUrls":["https://docs.aws.amazon.com/awscloudtrail/latest/userguide/cloudtrail-log-file-validation-intro.html"],"title":"AWS CloudTrail：摘要鏈與完整性驗證","titleEn":"AWS CloudTrail: digest chains and integrity validation","why":"用兩課的可觀察驗收條件比較模型邊界：交付100請求對照、90個auditID索引、缺席清單與敏感內容排除測試。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver a hundred-request comparison, ninety-auditID index, missing-request list and sensitive-content exclusion tests.","difference":"區分啟用摘要產生與實際執行驗證，檢查日誌摘要、簽署信任與前一摘要連結。","differenceEn":"Distinguish enabling digest delivery from performing validation; inspect log hashes, signer trust and previous-digest links.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["請求覆蓋=至少有必要稽核證據的唯一auditID/已知請求；Metadata與RequestResponse資料暴露程度不同。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 已知100個合成請求，稽核有180列但只涵蓋90個auditID；10個請求完全缺席。 覆蓋率90/100=90%；180列不能宣稱180%覆蓋。","完整性驗證覆蓋=已驗證時段/應有時段；雜湊相符不單獨證明來源身分或完整收集。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 24個小時應各有一份摘要；收到23份，其中22份連結與日誌驗證通過。 已驗證覆蓋22/24=91.6667%；缺1份與失敗1份需分開列。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Request coverage counts unique auditIDs with required evidence; Metadata and RequestResponse expose different amounts of data. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. One hundred synthetic requests produce 180 audit rows covering ninety auditIDs; ten requests are absent. Coverage is 90%, not 180% merely because there are 180 rows.","Integrity-validation coverage is verified periods divided by expected periods; matching hashes alone prove neither source identity nor complete collection. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Twenty-four hourly digests are expected; twenty-three arrive, and twenty-two pass link and log validation. Verified coverage=22/24=91.6667%; distinguish one missing digest from one validation failure.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-086","referenceUrls":["https://docs.opensearch.org/latest/security-analytics/"],"title":"OpenSearch Security Analytics：攝取延遲與偵測時效","titleEn":"OpenSearch Security Analytics: ingestion lag and detection timeliness","why":"用兩課的可觀察驗收條件比較模型邊界：交付100請求對照、90個auditID索引、缺席清單與敏感內容排除測試。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver a hundred-request comparison, ninety-auditID index, missing-request list and sensitive-content exclusion tests.","difference":"建立端到端時間戳與佇列指標，證明無警示可能是資料尚未到達，而不是事件不存在。","differenceEn":"Track end-to-end timestamps and queue metrics to show that no alert may mean data has not arrived.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["請求覆蓋=至少有必要稽核證據的唯一auditID/已知請求；Metadata與RequestResponse資料暴露程度不同。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 已知100個合成請求，稽核有180列但只涵蓋90個auditID；10個請求完全缺席。 覆蓋率90/100=90%；180列不能宣稱180%覆蓋。","在固定速率模型中，積壓增量=(到達率−處理率)×時間；真實系統還有突發、重試與批次。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 合成事件以120筆/秒到達，處理100筆/秒，起始無積壓，持續300秒。 積壓=(120−100)×300=6000筆。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Request coverage counts unique auditIDs with required evidence; Metadata and RequestResponse expose different amounts of data. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. One hundred synthetic requests produce 180 audit rows covering ninety auditIDs; ten requests are absent. Coverage is 90%, not 180% merely because there are 180 rows.","Under a fixed-rate model, backlog growth=(arrival−processing)×time; real systems add bursts, retries and batching. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Synthetic events arrive at 120 per second and process at 100 per second for 300 seconds from an empty queue. Backlog=(120−100)×300=6000 events.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-eee83c3856f83a67","url":"https://docs.aws.amazon.com/awscloudtrail/latest/userguide/cloudtrail-log-file-validation-intro.html","title":"Validating CloudTrail log integrity","titleEn":"Validating CloudTrail log integrity","publisher":"AWS","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-caf278a99f4e925c","url":"https://docs.opensearch.org/latest/security-analytics/","title":"OpenSearch Security Analytics","titleEn":"OpenSearch Security Analytics","publisher":"OpenSearch","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
